import{_ as i,o as e,c as l,a2 as n,j as a,a as t}from"./chunks/framework.DxqK4cCD.js";const u=JSON.parse('{"title":"HiFA4: Training-Free 4-bit FlashAttention on Ascend HIF4 NPUs for LLM Inference","description":"HiFA4通过Smooth-QK和P-Reordering机制，在无需训练和在线重建的前提下，首次在Ascend NPU上实现了高精度的4比特FlashAttention推理。","frontmatter":{"title":"HiFA4: Training-Free 4-bit FlashAttention on Ascend HIF4 NPUs for LLM Inference","description":"HiFA4通过Smooth-QK和P-Reordering机制，在无需训练和在线重建的前提下，首次在Ascend NPU上实现了高精度的4比特FlashAttention推理。","date":"2026-07-12","arxivId":"2607.04302","domain":"机器学习 · 人工智能 · 体系结构","level":"前沿","tags":["4比特量化","FlashAttention","Ascend NPU","大语言模型推理","训练后量化"],"originalUrl":"https://arxiv.org/abs/2607.04302","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-07-12/2607.04302.md"},"headers":[],"relativePath":"papers/daily/2026-07-12/2607.04302.md","filePath":"papers/daily/2026-07-12/2607.04302.md","lastUpdated":1786541753000}'),r={name:"papers/daily/2026-07-12/2607.04302.md"};function o(h,s,p,d,g,c){return e(),l("div",null,[...s[0]||(s[0]=[n("",15),a("ul",null,[a("li",null,[a("strong",null,"Smooth-QK机制"),t("：在RoPE之后，对Q和K矩阵进行逐通道的静态重缩放。具体来说，通过校准数据集（如MMLU的一个子集）统计出每个通道的缩放因子（scale factor）。对于Q矩阵，其缩放因子为 $s_Q = \\max(|Q|) / \\tau$，其中 $\\tau$ 是一个阈值；对于K矩阵，其缩放因子为 $s_K = \\tau / \\max(|K|)$。然后，将Q和K分别乘以各自的缩放因子：$Q' = Q \\cdot s_Q$，$K' = K \\cdot s_K$。这样做的目的是将K的数值范围压缩到一个对量化更友好的区间，而将Q的数值范围适当放大。由于K在后续的softmax计算中会被指数化，其量化误差会被放大，因此优先保证K的精度。")]),a("li",null,[a("strong",null,"P-Reordering机制"),t("：在标准的FlashAttention中，输出 $O = \\text{softmax}(QK^T)V$。其中softmax归一化因子 $l = \\sum_j \\exp(QK^T_j)$。在4比特量化场景下，我们得到的是量化后的注意力权重 $\\hat{P} = \\text{quant}(QK^T)$。P-Reordering的核心是使用 $\\hat{P}$ 来计算归一化因子 $\\hat{l} = \\sum_j \\exp(\\hat{P}"),a("em",{FP16:""},"j)$，而不是使用高精度的 $QK^T$。然后，输出 $O = \\hat{P} \\cdot V / \\hat{l}$。论文证明，这种操作引入了一个输出缩放误差 $\\epsilon$，使得 $O \\approx O"),t(" \\cdot (1 + \\epsilon)$。这个误差是全局一致的，可以通过一个简单的后处理缩放因子进行校正。")]),a("li",null,[a("strong",null,"误差分析与校正"),t("：论文通过理论分析和实验验证了P-Reordering引入的误差特性。在Qwen3-8B模型上，对所有3.6M个注意力块（tile）的测量显示，中位数误差 $\\bar{\\epsilon} = -0.064$，表明存在净概率质量损失（net probability-mass loss）。这意味着输出被系统地低估了约6.4%。因此，可以通过一个全局的缩放因子 $1/(1+\\bar{\\epsilon})$ 来校正输出。")]),a("li",null,[a("strong",null,"融合计算"),t("：P-Reordering的关键优势在于，归一化因子 $\\hat{l}$ 的计算可以融合到PV的Cube GEMM中。在计算 $\\hat{P} \\cdot V$ 的同时，可以累加 $\\exp(\\hat{P})$ 得到 $\\hat{l}$，从而避免了额外的内存读取和计算步骤，显著降低了延迟。")]),a("li",null,[a("strong",null,"Q-Mean辅助"),t("：对于Smooth-QK被禁用的模型（如LLaMA3.1-8B），HiFA4采用Q-Mean辅助策略。在量化Q和K时，使用Q矩阵的均值（mean）作为量化零点（zero-point）的偏移量，以减少量化误差。")])],-1),n("",58)])])}const k=i(r,[["render",o]]);export{u as __pageData,k as default};
